package com.supersports.support;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import org.springframework.web.client.RestClientException;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/v1") class SupportController{
 private final SupportRepository repo;private final RestClient orders;SupportController(SupportRepository repo,@Value("${orders.base-url}")String url){this.repo=repo;orders=RestClient.builder().baseUrl(url).build();}
 @PostMapping("/customer/support/tickets") Map<String,Object> create(@RequestBody NewTicket request,@AuthenticationPrincipal Jwt jwt){if(request==null||request.operationId()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);if(request.orderId()!=null)verifyOrder(request.orderId(),jwt);try{return repo.create(UUID.randomUUID(),jwt.getSubject(),request.orderId(),request.subject(),request.message(),request.operationId());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid ticket fields");}}
 @GetMapping("/customer/support/tickets") List<Map<String,Object>> mine(@AuthenticationPrincipal Jwt jwt){return repo.mine(jwt.getSubject());}
 @GetMapping("/customer/support/tickets/{id}") Map<String,Object> detail(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){var value=repo.detail(id,jwt.getSubject(),false);if(value==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return value;}
 @PostMapping("/customer/support/tickets/{id}/messages") Map<String,Object> customerMessage(@PathVariable UUID id,@RequestBody Message request,@AuthenticationPrincipal Jwt jwt){return addMessage(id,jwt.getSubject(),false,request);}
 @GetMapping("/operator/support/tickets") List<Map<String,Object>> queue(){return repo.queue();}
 @GetMapping("/operator/support/tickets/{id}") Map<String,Object> operatorDetail(@PathVariable UUID id){var value=repo.detail(id,"",true);if(value==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return value;}
 @PostMapping("/operator/support/tickets/{id}/messages") Map<String,Object> operatorMessage(@PathVariable UUID id,@RequestBody Message request,@AuthenticationPrincipal Jwt jwt){return addMessage(id,"",true,jwt.getSubject(),request);}
 @PutMapping("/operator/support/tickets/{id}/status") Map<String,Object> status(@PathVariable UUID id,@RequestBody Status request,@AuthenticationPrincipal Jwt jwt){try{return repo.transition(id,request.status(),jwt.getSubject(),request.reason());}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 private Map<String,Object> addMessage(UUID id,String owner,boolean operator,Message request){return addMessage(id,owner,operator,operator?"operator":owner,request);}
 private Map<String,Object> addMessage(UUID id,String owner,boolean operator,String actor,Message request){if(request==null||request.operationId()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);try{return repo.message(id,owner,operator,actor,request.body(),request.operationId());}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 private void verifyOrder(UUID order,Jwt jwt){try{var proof=orders.get().uri("/api/v1/orders/{id}/verified-ownership",order).headers(h->h.setBearerAuth(jwt.getTokenValue())).retrieve().body(Map.class);if(proof==null||!Boolean.TRUE.equals(proof.get("verified")))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}catch(org.springframework.web.client.HttpClientErrorException.NotFound e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Linked order is not owned by this customer");}catch(RestClientException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Order ownership verification is unavailable");}}
 record NewTicket(UUID orderId,String subject,String message,UUID operationId){}record Message(String body,UUID operationId){}record Status(String status,String reason){}
}
